import{surfaceColor,perspective,solidStage}from'./material.js';
import{TenBase,fmt,svgEl}from'./ten-base.js';import{clamp}from'../math.js';import{combinedSolid}from'../ten-math.js';
export default class TenSolid extends TenBase{
 constructor(host,ctx){super(host,ctx);this.rx=.25;this.ry=.65;this.zoom=1;this.pointers=new Map();this.listen(this.svg,'pointerdown',e=>{this.pointers.set(e.pointerId,[e.clientX,e.clientY]);this.svg.setPointerCapture(e.pointerId);this.rot=[e.clientX,e.clientY]});this.listen(this.svg,'pointermove',e=>{if(!this.pointers.has(e.pointerId))return;this.pointers.set(e.pointerId,[e.clientX,e.clientY]);if(this.pointers.size===2){let[a,b]=[...this.pointers.values()],d=Math.hypot(a[0]-b[0],a[1]-b[1]);if(this.pinch)this.zoom=clamp(this.zoom*d/this.pinch,.5,2);this.pinch=d}else if(this.rot){this.ry+=(e.clientX-this.rot[0])*.012;this.rx+=(e.clientY-this.rot[1])*.012}this.rot=[e.clientX,e.clientY];this.changed=true;this.draw();ctx.onChange?.()});for(let name of['pointerup','pointercancel'])this.listen(this.svg,name,e=>{this.pointers.delete(e.pointerId);this.rot=null;this.pinch=null});this.listen(this.svg,'wheel',e=>{e.preventDefault();this.zoom=clamp(this.zoom-e.deltaY*.001,.5,2);this.draw()},{passive:false});this.listen(this.svg,'keydown',e=>{let d={ArrowLeft:[0,-.1],ArrowRight:[0,.1],ArrowUp:[-.1,0],ArrowDown:[.1,0]}[e.key];if(d){e.preventDefault();this.rx+=d[0];this.ry+=d[1];this.draw()}if(e.key==='+'||e.key==='-'){e.preventDefault();this.zoom=clamp(this.zoom+(e.key==='+'?.1:-.1),.5,2);this.draw()}});this.listen(document,'visibilitychange',()=>{this.last=0;if(!document.hidden&&this.playing)this.animate()});this.draw()}
 rotate([x,y,z]){let X=x*Math.cos(this.ry)+z*Math.sin(this.ry),Z=-x*Math.sin(this.ry)+z*Math.cos(this.ry);return[X,y*Math.cos(this.rx)-Z*Math.sin(this.rx),y*Math.sin(this.rx)+Z*Math.cos(this.rx)]}
 draw(){this.clear(false);solidStage(this.svg);let mode=this.mode,r=this.v||2,h=this.h||3,k=this.k||3,R=mode==='cavity'?3:r,total=mode==='cone-cylinder'?h+k:mode==='hemisphere-cylinder'?h+r:h,n=this.ctx.lowpower?16:32,faces=[],add=(points,color=0)=>faces.push({points,color}),point=(rr,y,a)=>[rr*Math.cos(a),y,rr*Math.sin(a)];
 for(let i=0;i<n;i++){let a=i*2*Math.PI/n,b=(i+1)*2*Math.PI/n;if(mode!=='cavity'||Math.sin((a+b)/2)<=.2)add([point(R,0,a),point(R,0,b),point(R,h,b),point(R,h,a)]);if(mode==='cone-cylinder')add([point(r,h,a),point(r,h,b),[0,h+k,0]],1);if(mode==='cavity')add([point(R,h,a),point(R,h,b),point(r,h,b),point(r,h,a)],1)}add(Array.from({length:n},(_,i)=>point(R,0,i*2*Math.PI/n)),0);
 if(mode!=='cone-cylinder'){for(let j=0;j<n/4;j++)for(let i=0;i<n;i++){let a=i*2*Math.PI/n,b=(i+1)*2*Math.PI/n,u=j*Math.PI/2/(n/4),v=(j+1)*Math.PI/2/(n/4),p=(q,t)=>point(r*Math.cos(q),h+(mode==='cavity'?-1:1)*r*Math.sin(q),t);add([p(u,a),p(u,b),p(v,b),p(v,a)],1)}}
 let scale=220/Math.max(2*R,total)*this.zoom,center=total/2,proj=p=>{let q=this.rotate([p[0],p[1]-center,p[2]]);return perspective(q,scale,300,200)};faces.map(f=>({...f,q:f.points.map(proj)})).sort((a,b)=>a.q.reduce((s,p)=>s+p[2],0)/a.q.length-b.q.reduce((s,p)=>s+p[2],0)/b.q.length).forEach(f=>{let a=f.q[0],u=f.q[1].map((x,i)=>x-a[i]),v=f.q[2].map((x,i)=>x-a[i]),normal=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],length=Math.hypot(...normal)||1,brightness=.4+.6*Math.abs((normal[0]*.5+normal[1]*1+normal[2]*.3)/(length*Math.sqrt(1.34))),base=f.color?[100,178,206]:[108,196,159],color=`rgb(${base.map(x=>Math.round(x*brightness)).join(',')})`;this.svg.append(svgEl('path',{d:f.q.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ')+'Z',fill:surfaceColor(f.points.map(p=>this.rotate([p[0],p[1]-center,p[2]])),base),stroke:'none'}))});
 if(this.labels){let a=proj([0,h,0]),b=proj([r,h,0]);this.svg.append(svgEl('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],stroke:'#f0c775','stroke-width':3}));this.svg.append(svgEl('text',{x:(a[0]+b[0])/2,y:(a[1]+b[1])/2-8},`r = ${r} cm`))}
 let q=combinedSolid(mode,r,h,k),s=(en,hi)=>this.say(en,hi),form=mode==='cone-cylinder'?`A = 2πrh + πr√(r²+H²) + πr²\nV = πr²h + πr²H/3`:mode==='hemisphere-cylinder'?`A = 2πrh + 3πr²\nV = πr²h + 2πr³/3`:`R = 3 cm; A = 2πRh + 2πR² + πr²\nV = πR²h − 2πr³/3`;this.report([form,`r = ${r} cm; h = ${h} cm${mode==='cone-cylinder'?`; H = ${k} cm; l = ${fmt(q.slant)} cm`:''}`,`${s('Exposed surface area','बाहरी / खुला पृष्ठीय क्षेत्रफल')} ≈ ${fmt(q.area)} cm²`,`${s('Material volume','पदार्थ का आयतन')} ≈ ${fmt(q.volume)} cm³`],mode==='cavity'?['Cutaway exposes the hollow for viewing; artificial cut faces are not counted. Cavity depth r never exceeds h.','खोखला भाग दिखाने के लिए काटकर दृश्य बनाया है; कृत्रिम कटे चेहरे क्षेत्रफल में नहीं गिने हैं। खोखले भाग की गहराई r, h से अधिक नहीं है।']:['The common circular interface is inside the solid and is excluded from exposed area.','साझी वृत्ताकार सतह ठोस के अंदर है; खुले क्षेत्रफल में नहीं गिनी जाती।']);}
 animate(){if(this.frame||!this.playing)return;const run=time=>{this.frame=null;if(!this.playing||document.hidden)return;let dt=this.last?Math.max(0,Math.min(.1,(time-this.last)/1000)):0;this.last=time;this.ry+=dt*.45*this.speed;if(!this.ctx.lowpower||!this.lastDraw||time-this.lastDraw>=32){this.draw();this.lastDraw=time}this.frame=requestAnimationFrame(run)};this.frame=requestAnimationFrame(run)}
 pause(){this.playing=!this.playing;this.last=0;if(this.playing)this.animate();else{cancelAnimationFrame(this.frame);this.frame=null}return this.playing}
 resetView(){this.rx=.25;this.ry=.65;this.zoom=1;this.draw()}
}
